namespace DcxManager.Gcp;

/// <summary>
/// The parts of Google Cloud the app exposes (0.2.0; 0.4.0 added managed instance groups, instance templates, machine
/// images, Cloud Functions, Artifact Registry, routes, Cloud Routers / NAT, backend services, health checks, SSL
/// certificates, VPN tunnels, Pub/Sub and Cloud SQL on-demand backups), one screen per resource type, generated by the shared cloud
/// engine (ADR-020) like the other providers. Paths are full URLs on the allow-listed API hosts (<see cref="GcpClient.Hosts"/>)
/// with <see cref="GcpClient.Project"/> for the project id. Compute items are addressed by their own path ({path:_self},
/// from selfLink, segment-escaped); the others by name. Changes are long-running in Google Cloud; <see cref="GcpClient"/>
/// follows each one to the end. Read-only projects (the default) refuse every change before it is sent.
/// Not exposed (deliberately): service-account keys, Secret Manager, Cloud SQL users and passwords, object contents,
/// the serial console (interactive, WebSocket) and IAM (identity and access stay in the Google Cloud console).
/// </summary>
public static class GcpCatalog
{
    private const string P = GcpClient.Project;
    private const string Compute = "https://compute.googleapis.com/compute/v1/projects/" + P;
    private const string ComputeItem = "https://compute.googleapis.com{path:_self}";
    private const string Dns = "https://dns.googleapis.com/dns/v1/projects/" + P;
    private const string Gke = "https://container.googleapis.com/v1/projects/" + P;
    private const string Sql = "https://sqladmin.googleapis.com/v1/projects/" + P;
    // 0.4.0 additions (DarkCipher0x: "include all features"): Cloud Functions, Artifact Registry, Pub/Sub, more Compute screens.
    private const string Functions = "https://cloudfunctions.googleapis.com/v2/projects/" + P;
    private const string Artifacts = "https://artifactregistry.googleapis.com/v1/projects/" + P;
    private const string PubSub = "https://pubsub.googleapis.com/v1/projects/" + P;

    public static readonly string[] GroupOrder = { "Compute", "Containers & apps", "Storage", "Network", "DNS", "Databases", "Messaging", "Reference" };

    private static ActionDef Post(string label, string verb, string? confirm = null, bool danger = false, string? when = null, string? tip = null) =>
        new(label, "POST", ComputeItem + "/" + verb, Confirm: confirm, Danger: danger, When: when, Tip: tip);

