    {
        Title = "VM instances", Group = "Compute", Path = Compute + "/aggregated/instances?returnPartialSuccess=true", Key = "items", NameField = "name", Icon = "▣",
        ItemPath = ComputeItem, StatusField = "status", IsInstance = true, TypeToDelete = true,
        Description = "Compute Engine VMs in every zone. Deleting a VM deletes its boot disk unless it was set to keep it.",
        Columns = new Col[] { new("name", "Name", 170), new("status", "Status", 90), new("_zone", "Zone", 120), new("_type", "Machine type", 120), new("_ip", "External IP", 115), new("_internal", "Internal IP", 105), new("creationTimestamp", "Created", 150) },
        Actions = new ActionDef[]
        {
            Post("▶ Start", "start", when: "TERMINATED"),
            Post("■ Stop", "stop", "Stop {name}? It shuts down (billing for its CPU and memory stops; disks are still billed).", true, "RUNNING"),
            Post("⟲ Reset (hard)", "reset", "Hard-reset {name}? Like pulling the power: unsaved data is lost.", true, "RUNNING"),
            Post("⏸ Suspend", "suspend", "Suspend {name}? Its memory is saved to disk and it stops running.", false, "RUNNING"),
            Post("▶ Resume", "resume", when: "SUSPENDED"),
            new("Change machine type…", "", "", Special: "resize", When: "TERMINATED", Tip: "Stop the VM first; then choose a machine type of its zone"),
            new("Serial output", "GET", ComputeItem + "/serialPort?port=1", ShowResult: true, Tip: "The VM's serial port 1 output (boot log)"),
        },
    };

